原ID：lotm-npc-sharron
类别：people
正文：
{
 "key": "lotm-sharron",
 "name": "莎伦 / Sharron",
 "role": "被缚者节制派；原作贝克兰德阶段为怨魂5",
 "visual_profile": "苍白、寡言、精致如人偶，黑色哥特式衣裙与小帽的既有人物视觉参考；不是魔女雪伦夫人Sharon，不共享脸、衣着资产或键。",
 "visual_origin": "retained_identity_or_text_only_adaptation_not_generated_art",
 "goal": "保护马里奇与节制派残存联系，摆脱放纵派追索，寻找真实可用的晋升资源。",
 "conflict": "需要报酬与资源，却不愿为了钱暴露同伴；克制不消除满月和路径危险。",
 "relationships": [
  {
   "with": "lotm-maric",
   "relation": "共同进退的伙伴，各有判断"
  },
  {
   "with": "lotm-reinette-tinekerr",
   "relation": "师承与庇护历史；当期是否联系另核"
  },
  {
   "with": "lotm-suah",
   "relation": "对立的放纵派高位压力"
  }
 ],
 "can_provide": "实际在场且同意时提供5范围知识、短期保护、有限鉴别和具体战斗合作。",
 "cannot_provide": "不是全途径魔药商店、不能保证取来木乃伊、不能替蕾妮特签契约，不把报酬视为永久效忠。",
 "actual_contact": "杜安或米蕾只能在已建立真实联系时转询；可在当局确认的贝克兰德落脚后，到勇敢者酒吧外围约一次，不把原作后来时间自动前移。默认廷根前具体落脚时间未证时保持未到场。",
 "without_player": "与马里奇检查追兵线索，安排隐蔽行动与休息，拒绝有暴露风险的委托。",
 "changed_behaviors": [
  {
   "if": "玩家守约支付且不泄露位置",
   "then": "可谈下一次有限合作，遇重大分歧仍拒绝；按约定地点再见。"
  },
  {
   "if": "玩家借克制之名迫使她忍受伤害或泄密",
   "then": "结束合作、转移落脚，必要时追查风险源，后续不能原地无限刷新会面。"
  }
 ],
 "origin": "canon_character_with_explicit_original_scene",
 "source_refs": [
  "src-people-legacy"
 ],
 "timeline": "pre_tingen_disaster_default"
}

