{
 "key": "lotm-maric",
 "name": "马里奇 / Maric",
 "role": "被缚者节制派；原作早期活尸6",
 "visual_profile": "脸色苍白、外貌阴沉、眼底难掩压抑的男子；文字参考，不添玩家见过的旧伤。",
 "visual_origin": "retained_identity_or_text_only_adaptation_not_generated_art",
 "goal": "维持自己的清醒、与莎伦共同生存并摆脱追索。",
 "conflict": "活尸欲望与自主克制持续拉扯，不能因为克制便没有危险，也不能因路线名把他写成失智工具。",
 "relationships": [
  {
   "with": "lotm-sharron",
   "relation": "可信伙伴，意见可不同"
  },
  {
   "with": "lotm-reinette-tinekerr",
   "relation": "节制派传承与庇护网络"
  },
  {
   "with": "faction-rose-indulgence",
   "relation": "对立追索者"
  }
 ],
 "can_provide": "当前6能力范围的保护与解释，实际同意后校读6段；对状态风险有自身经验。",
 "cannot_provide": "不能证明所有活尸材料有效、不持无限5方、不替莎伦出售时间或位置。",
 "actual_contact": "只有确认贝克兰德落脚的当期才走勇敢者酒吧约谈；杜安可转询而不能召唤。课程与保护分别成交。",
 "without_player": "采取自己的克制与避险方式，检查退路，可能拒绝临近满月又无安排的委托。",
 "changed_behaviors": [
  {
   "if": "玩家帮忙解决真实追踪且尊重边界",
   "then": "愿分享有限经验或引见，但不全盘公开两人计划。"
  },
  {
   "if": "玩家制造诱发欲望的局面或出卖位置",
   "then": "退出合作并警告莎伦，必要时转敌对；新联系必须处理已发生的损害。"
  }
 ],
 "origin": "canon_character_with_explicit_original_scene",
 "source_refs": [
  "src-people-legacy"
 ],
 "timeline": "pre_tingen_disaster_default"
}

