{
 "key": "lotm-will-auceptin",
 "name": "威尔·昂赛汀 / Will Auceptin",
 "role": "命运之轮高位者；生命学派议长身份仅按二手层使用",
 "visual_profile": "既有形态视觉随当期化身确认；默认前廷根不固定成幼童或婴儿，后续已确认儿童形态才用相应形象，不以成人化外观覆盖。",
 "visual_origin": "retained_identity_or_text_only_adaptation_not_generated_art",
 "goal": "避免乌洛琉斯捕获自己的那份水银之蛇，争取命运契机并维护可利用的学派联系。",
 "conflict": "需要盟友和安全信息，又不能让外围信徒掌握自己当前化身；愿意帮助不等于允许用重启抹掉责任。",
 "relationships": [
  {
   "with": "lotm-ouroboros",
   "relation": "同途径争夺者，彼此目标相冲突；不是共同开店的老师"
  },
  {
   "with": "faction-life-school",
   "relation": "可影响组织但非每个成员都知道其状态"
  },
  {
   "with": "lotm-fool-klein",
   "relation": "原作后来的合作不得提前建立"
  }
 ],
 "can_provide": "仅在实际回应后给有限命运提示、自己愿意的交易及与当前状态相符的能力帮助。",
 "cannot_provide": "不售免费1特性、无限幸运、全世界时光倒流；未确认当前重启形态时不在亚伦住址自动出现。",
 "actual_contact": "奥斯在真实得到转交许可后递交范围明确的请求；实际回函或梦境联系须确认来源。保留r4纸鹤梦启的已核首部片段，但后期手段不能成为所有开局角色的通讯录。",
 "without_player": "变更藏身与联络方法、让学派外围任务继续而自己避免暴露；玩家不来仍面对乌洛琉斯压力。",
 "changed_behaviors": [
  {
   "if": "玩家确实保护当期安全信息且完成双方约定",
   "then": "可增加一次有限回复，仍逐件谈资源；下一次通过原保密渠道约定，不因一次合作交出唯一性。"
  },
  {
   "if": "玩家泄露化身或把未答复说成承诺",
   "then": "切断该渠道或改变身份，后续须重新建立信任，不自动追杀也不忘记泄露。"
  }
 ],
 "origin": "canon_character_with_explicit_original_scene",
 "source_refs": [
  "src-people-legacy"
 ],
 "timeline": "pre_tingen_disaster_default"
}

