{
 "key": "lotm-reinette-tinekerr",
 "name": "蕾妮特·缇尼科尔 / Reinette Tinekerr",
 "role": "节制派高位者；受损与恢复状态需按时点建立",
 "visual_profile": "哥特式宫廷裙、无首躯体与手提头颅为后续已确认形态参考；默认无当前可见形态，不能在初见描述前假装玩家已知。",
 "visual_origin": "retained_identity_or_text_only_adaptation_not_generated_art",
 "goal": "恢复自身、保护传承并对抗破坏节制派的高位敌手。",
 "conflict": "力量与完整状态受限，需要资源和盟友，却不愿为低阶请求耗尽自己。",
 "relationships": [
  {
   "with": "lotm-sharron",
   "relation": "老师与弟子，非玩家可随意借用的关系"
  },
  {
   "with": "lotm-suah",
   "relation": "曾导致其重大损失的对手"
  },
  {
   "with": "lotm-tolzna",
   "relation": "原信仰与高地历史，现污染必须区别"
  }
 ],
 "can_provide": "在真实可达、身份与恢复状态已确认时提供有限高位协助或知识判断，价格与风险由当次协议。",
 "cannot_provide": "默认没有克莱恩信使契约，不是免费传送/复活服务，不必为玩家牺牲自己的恢复进度。",
 "actual_contact": "优先经莎伦真实同意传信；灵界接触需要实际可用的方法与目标回应，不抄后来召唤词强行绑定。失败联系也可得到具体“未回应”结局。",
 "without_player": "寻找恢复所需的东西、维护节制派网络，选择避开无法承担的正面对抗。",
 "changed_behaviors": [
  {
   "if": "玩家确实交回与其恢复有关的真物且未侵害弟子",
   "then": "愿另谈有限协助，不把物件价值自动折成永久召唤次数。"
  },
  {
   "if": "玩家把她的残缺状态出卖给斯厄阿",
   "then": "切断渠道并采取反制，自保优先；后续无法沿旧联系无条件见面。"
  }
 ],
 "origin": "canon_character_with_explicit_original_scene",
 "source_refs": [
  "src-people-legacy"
 ],
 "timeline": "pre_tingen_disaster_default"
}

